svg.script:
    const route = document.getElementById('journeyRoute');
    const marker = document.getElementById('current-location-marker');
    const stops = {
      shire: {x:240, y:860},
      bywaterMill: {x:285, y:585},
      bree: {x:650, y:598},
      edoras: {x:790, y:382},
      isengard: {x:1124, y:748},
      minasTirith: {x:1324, y:222}
    };

    function moveMarkerTo(x, y) {
      marker.setAttribute('transform', `translate(${x} ${y})`);
    }

    function setMarkerAtProgress(progress) {
      const p = Math.max(0, Math.min(1, Number(progress)));
      const len = route.getTotalLength();
      const pt = route.getPointAtLength(len * p);
      moveMarkerTo(pt.x, pt.y);
    }

    function setMarkerAtStop(stopName) {
      const stop = stops[stopName];
      if (!stop) return false;
      moveMarkerTo(stop.x, stop.y);
      return true;
    }

    document.querySelectorAll('.hotspot').forEach(el => {
      el.addEventListener('click', () => setMarkerAtStop(el.dataset.stop));
    });

    // Expose helpers to the page/app using this SVG.
    window.setMarkerAtProgress = setMarkerAtProgress;
    window.setMarkerAtStop = setMarkerAtStop;
